Este ejemplo muestra el uso del método .

using System;
using Bansi.Drawing.Printing.Common;
namespace Example
{
    public class Program
    {
        public void Main()
        {

           if (Printer.Exists("NombreImpresora"))
           {
              Console.WriteLine("Existe");
           }
           else
           {
              Console.WriteLine("No Existe");
           }
        }
    }
}

