En este ejemplo vemos el uso de la clase , usando el
método .


using System;
using Bansi.Drawing.Printing;

namespace Example
{
    public class Program
    {
        public void Main()
        {
            IPrinter printer;

            //Este método devuelve una interfaz IPrinter configurada.
            printer = PrinterFactory.Create("NombreDeRamaDeMiImpresora");
            Console.Write(printer.PrinterName);
        }
    }
}
